export type BrickType = number;
export type Direction = "up" | "down" | "left" | "right";
export type ItemType = "restart" | "undo" | "hint" | "swap" | "clearType" | "shuffle";

export interface Word {
  id: string;
  spelling: string;
  meaning: string;
  wrongCount: number;
}

export type QuizQuestionType = "choice" | "spelling";

export interface QuizChoiceQuestion {
  type: "choice";
  word: Word;
  options: string[];
  correctIndex: number;
}

export interface QuizSpellingQuestion {
  type: "spelling";
  word: Word;
}

export type QuizQuestion = QuizChoiceQuestion | QuizSpellingQuestion;

export interface QuizSession {
  questions: QuizQuestion[];
  currentIndex: number;
  correctCount: number;
  wrongCount: number;
  isFinished: boolean;
  isWon: boolean;
  userAnswer: string;
}

export interface Inventory {
  restart: number;
  undo: number;
  hint: number;
  swap: number;
  clearType: number;
  shuffle: number;
}

export type ActiveTool = null | "swap" | "clearType";

export interface ShopItem {
  type: ItemType;
  price: number;
  id: string;
}

export interface Position {
  row: number;
  col: number;
}

export interface Cell {
  row: number;
  col: number;
  brick: BrickType | null;
}

export type Board = Cell[][];

export interface ConnectedGroup {
  type: BrickType;
  positions: Position[];
}

export interface GameState {
  board: Board;
  selectedGroup: ConnectedGroup | null;
  selectedCell: Position | null;
  pairCandidates: Position[];
  validMoveTargets: Position[];
  score: number;
  clearedPairs: number;
  remainingBricks: number;
  isWon: boolean;
  isFailed: boolean;
  level: number;
  moveHistory: Board[];
  clearingCells: Position[];
  hintCells: Position[];
  coins: number;
  inventory: Inventory;
  activeTool: ActiveTool;
  swapFirstCell: Position | null;
}

export const ROWS = 14;
export const COLS = 10;
export const BRICK_TYPES = 35;
export const BRICKS_PER_TYPE = 4;
export const CLEAR_THRESHOLD = 2;

