import {
  Board,
  Position,
  ConnectedGroup,
  Direction,
  ROWS,
  COLS,
  BRICK_TYPES,
  BRICKS_PER_TYPE,
} from "@/types/game";

export function createEmptyBoard(): Board {
  const board: Board = [];
  for (let row = 0; row < ROWS; row++) {
    const rowArr = [];
    for (let col = 0; col < COLS; col++) {
      rowArr.push({ row, col, brick: null });
    }
    board.push(rowArr);
  }
  return board;
}

function shuffle<T>(array: T[]): T[] {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

export function initializeBoard(): Board {
  const board = createEmptyBoard();

  const allBricks: number[] = [];
  for (let type = 0; type < BRICK_TYPES; type++) {
    for (let i = 0; i < BRICKS_PER_TYPE; i++) {
      allBricks.push(type);
    }
  }

  const shuffled = shuffle(allBricks);
  let idx = 0;

  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      board[row][col].brick = shuffled[idx];
      idx++;
    }
  }

  return board;
}

export function findConnectedGroup(
  board: Board,
  startRow: number,
  startCol: number
): ConnectedGroup | null {
  const cell = board[startRow]?.[startCol];
  if (!cell || cell.brick === null) return null;

  const type = cell.brick;
  const visited = new Set<string>();
  const positions: Position[] = [];
  const queue: Position[] = [{ row: startRow, col: startCol }];
  const directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  while (queue.length > 0) {
    const pos = queue.shift()!;
    const key = `${pos.row},${pos.col}`;
    if (visited.has(key)) continue;
    visited.add(key);

    const cell = board[pos.row]?.[pos.col];
    if (!cell || cell.brick !== type) continue;

    positions.push(pos);

    for (const [dr, dc] of directions) {
      const newRow = pos.row + dr;
      const newCol = pos.col + dc;
      const newKey = `${newRow},${newCol}`;
      if (
        newRow >= 0 &&
        newRow < ROWS &&
        newCol >= 0 &&
        newCol < COLS &&
        !visited.has(newKey)
      ) {
        queue.push({ row: newRow, col: newCol });
      }
    }
  }

  return { type, positions };
}

export function canMoveGroup(
  board: Board,
  group: ConnectedGroup,
  targetRow: number,
  targetCol: number
): boolean {
  if (group.positions.length === 0) return false;

  const minRow = Math.min(...group.positions.map((p) => p.row));
  const minCol = Math.min(...group.positions.map((p) => p.col));

  const offsetRow = targetRow - minRow;
  const offsetCol = targetCol - minCol;

  const groupKeys = new Set(
    group.positions.map((p) => `${p.row},${p.col}`)
  );

  for (const pos of group.positions) {
    const newRow = pos.row + offsetRow;
    const newCol = pos.col + offsetCol;

    if (newRow < 0 || newRow >= ROWS || newCol < 0 || newCol >= COLS) {
      return false;
    }

    const targetCell = board[newRow][newCol];
    const newKey = `${newRow},${newCol}`;

    if (targetCell.brick !== null && !groupKeys.has(newKey)) {
      return false;
    }
  }

  return true;
}

export function moveGroup(
  board: Board,
  group: ConnectedGroup,
  targetRow: number,
  targetCol: number
): Board {
  const newBoard = board.map((row) => row.map((cell) => ({ ...cell })));

  const minRow = Math.min(...group.positions.map((p) => p.row));
  const minCol = Math.min(...group.positions.map((p) => p.col));

  const offsetRow = targetRow - minRow;
  const offsetCol = targetCol - minCol;

  const oldPositions = group.positions.map((p) => ({
    row: p.row,
    col: p.col,
  }));

  for (const pos of oldPositions) {
    newBoard[pos.row][pos.col].brick = null;
  }

  for (const pos of group.positions) {
    const newRow = pos.row + offsetRow;
    const newCol = pos.col + offsetCol;
    newBoard[newRow][newCol].brick = group.type;
  }

  return newBoard;
}

export function findValidMoveTargets(
  board: Board,
  group: ConnectedGroup
): Position[] {
  if (group.positions.length === 0) return [];

  const targets: Position[] = [];
  const groupKeys = new Set(
    group.positions.map((p) => `${p.row},${p.col}`)
  );

  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      if (groupKeys.has(`${row},${col}`)) continue;
      if (canMoveGroup(board, group, row, col)) {
        targets.push({ row, col });
      }
    }
  }

  return targets;
}

export function findAdjacentSameType(
  board: Board,
  row: number,
  col: number
): Position[] {
  const cell = board[row]?.[col];
  if (!cell || cell.brick === null) return [];

  const type = cell.brick;
  const result: Position[] = [];
  const directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  for (const [dr, dc] of directions) {
    let curRow = row + dr;
    let curCol = col + dc;

    while (
      curRow >= 0 &&
      curRow < ROWS &&
      curCol >= 0 &&
      curCol < COLS
    ) {
      const curCell = board[curRow][curCol];
      if (curCell.brick === null) {
        curRow += dr;
        curCol += dc;
        continue;
      }
      if (curCell.brick === type) {
        result.push({ row: curRow, col: curCol });
      }
      break;
    }
  }

  return result;
}

export function clearPair(board: Board, pos1: Position, pos2: Position): Board {
  const newBoard = board.map((row) => row.map((cell) => ({ ...cell })));
  newBoard[pos1.row][pos1.col].brick = null;
  newBoard[pos2.row][pos2.col].brick = null;
  return newBoard;
}

export function countRemainingBricks(board: Board): number {
  let count = 0;
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      if (board[row][col].brick !== null) count++;
    }
  }
  return count;
}

export function deepCloneBoard(board: Board): Board {
  return board.map((row) => row.map((cell) => ({ ...cell })));
}

const DIR_DELTA: Record<Direction, [number, number]> = {
  up: [-1, 0],
  down: [1, 0],
  left: [0, -1],
  right: [0, 1],
};

export function findPushChain(
  board: Board,
  startRow: number,
  startCol: number,
  direction: Direction
): Position[] {
  const cell = board[startRow]?.[startCol];
  if (!cell || cell.brick === null) return [];

  const [dr, dc] = DIR_DELTA[direction];
  const chain: Position[] = [{ row: startRow, col: startCol }];
  const visited = new Set<string>([`${startRow},${startCol}`]);

  let curRow = startRow + dr;
  let curCol = startCol + dc;
  while (
    curRow >= 0 &&
    curRow < ROWS &&
    curCol >= 0 &&
    curCol < COLS &&
    board[curRow][curCol].brick !== null
  ) {
    const key = `${curRow},${curCol}`;
    if (visited.has(key)) break;
    visited.add(key);
    chain.push({ row: curRow, col: curCol });
    curRow += dr;
    curCol += dc;
  }

  return chain;
}

export function canPushChain(
  board: Board,
  chain: Position[],
  direction: Direction
): boolean {
  if (chain.length === 0) return false;

  const [dr, dc] = DIR_DELTA[direction];
  const chainKeys = new Set(chain.map((p) => `${p.row},${p.col}`));

  for (const pos of chain) {
    const newRow = pos.row + dr;
    const newCol = pos.col + dc;

    if (newRow < 0 || newRow >= ROWS || newCol < 0 || newCol >= COLS) {
      return false;
    }

    const targetCell = board[newRow][newCol];
    const targetKey = `${newRow},${newCol}`;

    if (targetCell.brick !== null && !chainKeys.has(targetKey)) {
      return false;
    }
  }

  return true;
}

export function pushChain(
  board: Board,
  chain: Position[],
  direction: Direction
): Board {
  if (chain.length === 0) return board;

  const [dr, dc] = DIR_DELTA[direction];
  const newBoard = deepCloneBoard(board);

  const bricks: (number | null)[] = chain.map(
    (p) => board[p.row][p.col].brick
  );

  for (const pos of chain) {
    newBoard[pos.row][pos.col].brick = null;
  }

  for (let i = 0; i < chain.length; i++) {
    const newRow = chain[i].row + dr;
    const newCol = chain[i].col + dc;
    newBoard[newRow][newCol].brick = bricks[i];
  }

  return newBoard;
}

export function maxPhysicalPushSteps(
  board: Board,
  startRow: number,
  startCol: number,
  direction: Direction
): number {
  const initialChain = findPushChain(board, startRow, startCol, direction);
  if (initialChain.length === 0) return 0;

  const [dr, dc] = DIR_DELTA[direction];
  let steps = 0;
  let currentBoard = board;
  let chain = initialChain;

  while (true) {
    if (!canPushChain(currentBoard, chain, direction)) break;
    currentBoard = pushChain(currentBoard, chain, direction);
    chain = chain.map((p) => ({ row: p.row + dr, col: p.col + dc }));
    steps++;
  }

  return steps;
}

export function maxPushSteps(
  board: Board,
  startRow: number,
  startCol: number,
  direction: Direction
): number {
  let steps = 0;
  let currentBoard = board;
  let curRow = startRow;
  let curCol = startCol;
  let lastChain: Position[] = [];

  while (true) {
    const chain = findPushChain(currentBoard, curRow, curCol, direction);
    if (chain.length === 0) break;
    if (!canPushChain(currentBoard, chain, direction)) break;
    currentBoard = pushChain(currentBoard, chain, direction);
    const [dr, dc] = DIR_DELTA[direction];
    curRow += dr;
    curCol += dc;
    steps++;
    lastChain = chain.map((p) => ({ row: p.row + dr, col: p.col + dc }));
  }

  if (steps === 0) return 0;

  const pairs = findChainAdjacentPairs(currentBoard, lastChain);
  if (pairs.length === 0) return 0;

  return steps;
}

export function hasAnyAdjacentPair(board: Board): boolean {
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      const type = board[row][col].brick;
      if (type === null) continue;
      const adj = findAdjacentSameType(board, row, col);
      if (adj.length > 0) return true;
    }
  }
  return false;
}

export function findChainAdjacentPairs(
  board: Board,
  chain: Position[]
): Array<[Position, Position]> {
  const pairs: Array<[Position, Position]> = [];
  const chainSet = new Set(chain.map((p) => `${p.row},${p.col}`));
  const seen = new Set<string>();

  for (const pos of chain) {
    const type = board[pos.row]?.[pos.col]?.brick;
    if (type === null || type === undefined) continue;

    const adjacents = findAdjacentSameType(board, pos.row, pos.col);
    for (const adj of adjacents) {
      const key = [
        `${pos.row},${pos.col}`,
        `${adj.row},${adj.col}`,
      ].sort().join("|");
      if (!seen.has(key)) {
        seen.add(key);
        pairs.push([pos, adj]);
      }
    }
  }

  return pairs;
}

export function clearChainPairs(
  board: Board,
  chain: Position[]
): { board: Board; clearedCount: number } {
  let resultBoard = board;
  let totalCleared = 0;
  let iterChain = chain;

  while (true) {
    const pairs = findChainAdjacentPairs(resultBoard, iterChain);
    if (pairs.length === 0) break;

    const clearedPositions = new Set<string>();
    for (const [p1, p2] of pairs) {
      const k1 = `${p1.row},${p1.col}`;
      const k2 = `${p2.row},${p2.col}`;
      if (!clearedPositions.has(k1) && !clearedPositions.has(k2)) {
        resultBoard = clearPair(resultBoard, p1, p2);
        clearedPositions.add(k1);
        clearedPositions.add(k2);
        totalCleared++;
      }
    }

    iterChain = iterChain.filter(
      (p) => !clearedPositions.has(`${p.row},${p.col}`)
    );
    if (clearedPositions.size === 0) break;
  }

  return { board: resultBoard, clearedCount: totalCleared };
}

export function findCellAdjacentPairs(
  board: Board,
  pos: Position
): Array<[Position, Position]> {
  const pairs: Array<[Position, Position]> = [];
  const type = board[pos.row]?.[pos.col]?.brick;
  if (type === null || type === undefined) return pairs;

  const adjacents = findAdjacentSameType(board, pos.row, pos.col);
  for (const adj of adjacents) {
    pairs.push([pos, adj]);
  }

  return pairs;
}

export function clearCellPairs(
  board: Board,
  pos: Position
): { board: Board; clearedCount: number; clearedCells: Position[] } {
  let resultBoard = board;
  let totalCleared = 0;
  const allCleared: Position[] = [];
  let currentPos = pos;

  while (true) {
    const pairs = findCellAdjacentPairs(resultBoard, currentPos);
    if (pairs.length === 0) break;

    const [p1, p2] = pairs[0];
    resultBoard = clearPair(resultBoard, p1, p2);
    allCleared.push(p1, p2);
    totalCleared++;

    if (`${p1.row},${p1.col}` === `${currentPos.row},${currentPos.col}`) {
      break;
    }
  }

  return { board: resultBoard, clearedCount: totalCleared, clearedCells: allCleared };
}

export function findAllEliminablePairs(
  board: Board
): Array<[Position, Position]> {
  const pairs: Array<[Position, Position]> = [];
  const seen = new Set<string>();

  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const type = board[r][c].brick;
      if (type === null) continue;

      const adjacents = findAdjacentSameType(board, r, c);
      for (const adj of adjacents) {
        const key = [
          `${r},${c}`,
          `${adj.row},${adj.col}`,
        ].sort().join("|");
        if (!seen.has(key)) {
          seen.add(key);
          pairs.push([{ row: r, col: c }, adj]);
        }
      }
    }
  }

  return pairs;
}

export function findAllMovableEliminable(
  board: Board
): Position[] {
  const result: Position[] = [];
  const seen = new Set<string>();
  const directions: Direction[] = ["up", "down", "left", "right"];

  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (board[r][c].brick === null) continue;

      const key = `${r},${c}`;
      if (seen.has(key)) continue;

      const currentAdjacents = findAdjacentSameType(board, r, c);
      if (currentAdjacents.length > 0) {
        seen.add(key);
        result.push({ row: r, col: c });
        continue;
      }

      let canEliminate = false;
      for (const dir of directions) {
        const initialChain = findPushChain(board, r, c, dir);
        if (initialChain.length === 0) continue;

        let currentBoard = board;
        let chain = initialChain;
        const [dr, dc] = DIR_DELTA[dir];

        while (canPushChain(currentBoard, chain, dir)) {
          currentBoard = pushChain(currentBoard, chain, dir);
          chain = chain.map((p) => ({ row: p.row + dr, col: p.col + dc }));

          const newRow = r + (chain[0].row - initialChain[0].row);
          const newCol = c + (chain[0].col - initialChain[0].col);
          const adjacents = findAdjacentSameType(currentBoard, newRow, newCol);
          if (adjacents.length > 0) {
            canEliminate = true;
            break;
          }
        }
        if (canEliminate) break;
      }

      if (canEliminate) {
        seen.add(key);
        result.push({ row: r, col: c });
      }
    }
  }

  return result;
}

export function findFirstEliminablePair(
  board: Board
): [Position, Position] | null {
  const directions: Direction[] = ["up", "down", "left", "right"];

  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (board[r][c].brick === null) continue;

      const currentAdjacents = findAdjacentSameType(board, r, c);
      if (currentAdjacents.length > 0) {
        return [{ row: r, col: c }, currentAdjacents[0]];
      }

      for (const dir of directions) {
        const initialChain = findPushChain(board, r, c, dir);
        if (initialChain.length === 0) continue;

        let currentBoard = board;
        let chain = initialChain;
        const [dr, dc] = DIR_DELTA[dir];

        while (canPushChain(currentBoard, chain, dir)) {
          currentBoard = pushChain(currentBoard, chain, dir);
          chain = chain.map((p) => ({ row: p.row + dr, col: p.col + dc }));

          const newRow = chain[0].row;
          const newCol = chain[0].col;
          const adjacents = findAdjacentSameType(currentBoard, newRow, newCol);
          if (adjacents.length > 0) {
            return [{ row: r, col: c }, adjacents[0]];
          }
        }
      }
    }
  }

  return null;
}
