import { memo } from "react";

const BRICK_EMOJIS: string[] = [
  "🍎", "🍊", "🍋", "🍇", "🍓",
  "🍑", "🍒", "🥝", "🍌", "🍉",
  "🍍", "🥭", "🍐", "🍏", "🍈",
  "🥥", "🍅", "🥑", "🌽", "🥕",
  "🍄", "🧅", "🥔", "🌶️", "🍆",
  "🥒", "🥬", "🥦", "🧄", "🐱",
  "🐶", "🐰", "🦊", "🐻", "🐼",
];

interface BrickCellProps {
  row: number;
  col: number;
  brick: number | null;
  isSelected: boolean;
  isInGroup: boolean;
  isCandidate: boolean;
  isMoveTarget: boolean;
  isClearing?: boolean;
  isShaking?: boolean;
  isHint?: boolean;
  isSwapFirst?: boolean;
  isToolActive?: boolean;
  offsetX?: number;
  offsetY?: number;
  onMouseDown?: (e: React.MouseEvent) => void;
  onClick?: () => void;
  onTouchStart?: (e: React.TouchEvent) => void;
}

const BrickCell = memo(function BrickCell({
  row,
  col,
  brick,
  isSelected,
  isInGroup,
  isCandidate,
  isMoveTarget,
  isClearing = false,
  isShaking = false,
  isHint = false,
  isSwapFirst = false,
  isToolActive = false,
  offsetX = 0,
  offsetY = 0,
  onMouseDown,
  onClick,
  onTouchStart,
}: BrickCellProps) {
  let cellClasses =
    "w-full aspect-square rounded-lg cursor-pointer flex items-center justify-center select-none touch-none overflow-hidden";

  if (brick === null) {
    cellClasses += " bg-slate-800/40 border border-slate-700/50 hover:bg-slate-700/40";
  } else {
    cellClasses += " border border-amber-200";
    if (isClearing) {
      cellClasses += " brick-clearing";
    } else if (isShaking) {
      cellClasses += " brick-shaking";
    } else if (isSwapFirst) {
      cellClasses += " ring-4 ring-violet-400 ring-opacity-90 scale-110 z-10 animate-pulse";
    } else if (isSelected) {
      cellClasses += " ring-4 ring-yellow-400 ring-opacity-90 scale-110 z-10";
    } else if (isCandidate) {
      cellClasses +=
        " ring-4 ring-emerald-400 ring-opacity-90 scale-105 animate-pulse";
    } else if (isHint) {
      cellClasses +=
        " ring-4 ring-cyan-400 ring-opacity-90 scale-105 animate-pulse";
    } else if (isInGroup) {
      cellClasses += " ring-2 ring-white/70";
    } else if (isToolActive) {
      cellClasses += " hover:ring-4 hover:ring-purple-400 hover:ring-opacity-80 hover:scale-105";
    }
  }

  const emoji = brick !== null ? BRICK_EMOJIS[brick] : null;

  const style: React.CSSProperties = {};
  if (brick !== null) {
    style.background =
      "linear-gradient(180deg, #fffef5 0%, #f5efd8 55%, #e8dcb8 100%)";
    style.boxShadow =
      "inset 0 2px 0 rgba(255,255,255,0.9), inset 0 -2px 0 rgba(180,160,110,0.4), 0 3px 0 rgba(160,140,90,0.55), 0 5px 10px rgba(0,0,0,0.18)";
  }
  if (offsetX !== 0 || offsetY !== 0) {
    style.transform = `translate(${offsetX}px, ${offsetY}px)`;
    style.zIndex = 20;
  }

  return (
    <div
      className={cellClasses}
      style={style}
      onMouseDown={onMouseDown}
      onClick={onClick}
      onTouchStart={onTouchStart}
    >
      {emoji && (
        <span
          className="leading-none"
          style={{
            fontSize: "clamp(18px, 70%, 36px)",
          }}
        >
          {emoji}
        </span>
      )}
    </div>
  );
});

export default BrickCell;
